#!/usr/bin/env python3
import json
import sys
import urllib.error
import urllib.request

ENDPOINT = "https://www.ensembl.org/data/graphql"


def graphql(query):
    payload = json.dumps({"query": query}).encode("utf-8")
    req = urllib.request.Request(
        ENDPOINT,
        data=payload,
        headers={"Content-Type": "application/json", "Accept": "application/json", "User-Agent": "Galaxy-SHH-GraphQL-probe/1.0"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=120) as response:
            body = response.read()
            return {"http_status": response.status, "response": json.loads(body)}
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", "replace")
        return {"http_status": exc.code, "error_body": body}


